package com.feifei.phonebridge;
import android.app.*;
import android.graphics.Color;
import android.widget.*;
import android.view.View;
import org.json.*;

final class TaskRecordDialog {
 static String state(String value){switch(value){case "completed":case "succeeded":return "已完成";case "current":case "running":return "进行中";case "paused":return "已暂停";case "skipped":return "无需执行";case "pending":case "queued":return "未开始";case "cancelled":case "stopped":return "已结束";case "failed":return "已停止";default:return value;}}
 static TextView text(Activity a,String value,int size){TextView v=new TextView(a);v.setText(value);v.setTextSize(size);v.setTextColor(Color.rgb(36,56,59));v.setPadding(0,MobileUi.dp(a,4),0,MobileUi.dp(a,4));return v;}
 static void show(Activity a,JSONObject job){ScrollView scroll=new ScrollView(a);LinearLayout page=new LinearLayout(a);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(24,12,24,16);scroll.addView(page);String mode=job.optString("control_state","active");page.addView(text(a,mode.equals("active")?state(job.optString("status")):mode.equals("paused")?"已暂停":"正在处理控制指令",14));if(!job.optString("error_message").isEmpty())page.addView(text(a,job.optString("error_message"),13));JSONArray stages=job.optJSONArray("stages"),steps=job.optJSONArray("steps");if(stages!=null&&steps!=null)for(int i=0;i<stages.length();i++){JSONObject phase=stages.optJSONObject(i);if(phase==null)continue;TextView title=text(a,phase.optString("name")+"  ·  "+state(phase.optString("state")),16);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setPadding(0,24,0,8);page.addView(title);LinearLayout technical=new LinearLayout(a);technical.setOrientation(LinearLayout.VERTICAL);int count=0;for(int n=0;n<steps.length();n++){JSONObject step=steps.optJSONObject(n);if(step==null||!phase.optString("name").equals(step.optString("phase")))continue;LinearLayout row=row(a,step);if(step.optBoolean("technical")){technical.addView(row);count++;}else page.addView(row);}if(count>0){Button toggle=new Button(a);toggle.setAllCaps(false);toggle.setText("展开页面校验（"+count+"项）");technical.setVisibility(View.GONE);toggle.setOnClickListener(v->{boolean open=technical.getVisibility()==View.VISIBLE;technical.setVisibility(open?View.GONE:View.VISIBLE);toggle.setText(open?"展开页面校验":"收起页面校验");});page.addView(toggle);page.addView(technical);}}
 JSONArray events=job.optJSONArray("control_events");if(events!=null&&events.length()>0){page.addView(text(a,"任务控制记录",16));for(int i=0;i<events.length();i++){JSONObject event=events.optJSONObject(i);if(event==null)continue;String action=event.optString("action");page.addView(text(a,(action.equals("pause")?"暂停":action.equals("resume")?"继续":"结束")+" · "+time(event.optLong("at"))+" · "+(event.optString("origin").equals("bound_device")?"手机控制":"网页控制"),12));}}
 new AlertDialog.Builder(a).setTitle(job.optString("name","任务记录")).setView(scroll).setPositiveButton("关闭",null).show();}
 static LinearLayout row(Activity a,JSONObject step){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(0,8,0,8);LinearLayout heading=new LinearLayout(a);TextView name=text(a,step.optString("name"),14),state=text(a,state(step.optString("state")),12);heading.addView(name,new LinearLayout.LayoutParams(0,-2,1f));heading.addView(state);box.addView(heading);if(!step.optString("note").isEmpty())box.addView(text(a,step.optString("note"),12));Button receipt=new Button(a);receipt.setAllCaps(false);receipt.setText("查看回执");receipt.setTextSize(12);receipt.setOnClickListener(v->receipts(a,step));box.addView(receipt);return box;}
 static String time(long seconds){return new java.text.SimpleDateFormat("MM-dd HH:mm:ss",java.util.Locale.CHINA).format(new java.util.Date(seconds*1000));}
 static void receipts(Activity a,JSONObject step){StringBuilder body=new StringBuilder();JSONArray list=step.optJSONArray("receipts");if(list==null||list.length()==0)body.append(step.optString("note","尚无操作回执"));else{if(list.length()>10)body.append("共 ").append(list.length()).append(" 次回执，显示最近10次。\n\n");for(int i=Math.max(0,list.length()-10);i<list.length();i++){JSONObject receipt=list.optJSONObject(i);if(receipt==null)continue;body.append(state(receipt.optString("status"))).append(" · ").append(time(receipt.optLong("started_at"))).append("\n");if(!receipt.isNull("error"))body.append("执行信息：").append(receipt.optString("error")).append("\n");JSONArray evidence=receipt.optJSONArray("evidence");if(evidence!=null){int shown=0;for(int j=0;j<evidence.length()&&shown<6;j++){String value=evidence.optString(j);if(value.contains(":id/"))continue;body.append("· ").append(value).append("\n");shown++;}}body.append("\n");}}new AlertDialog.Builder(a).setTitle(step.optString("name","操作回执")).setMessage(body.toString()).setPositiveButton("关闭",null).show();}
}
